DROP POLICY IF EXISTS "ccp readable by linked accounts" ON public.curricular_correspondence_profiles; CREATE POLICY "ccp readable by linked accounts" ON public.curricular_correspondence_profiles FOR SELECT TO authenticated USING ((SELECT public.current_person_id()) IS NOT NULL OR (SELECT public.current_principal_id()) IS NOT NULL);
DROP POLICY IF EXISTS "ccp versions readable by linked accounts" ON public.curricular_correspondence_profile_versions; CREATE POLICY "ccp versions readable by linked accounts" ON public.curricular_correspondence_profile_versions FOR SELECT TO authenticated USING ((SELECT public.current_person_id()) IS NOT NULL OR (SELECT public.current_principal_id()) IS NOT NULL);
DROP POLICY IF EXISTS "ccp homologations readable by linked accounts" ON public.curricular_correspondence_profile_homologations; CREATE POLICY "ccp homologations readable by linked accounts" ON public.curricular_correspondence_profile_homologations FOR SELECT TO authenticated USING ((SELECT public.current_person_id()) IS NOT NULL OR (SELECT public.current_principal_id()) IS NOT NULL);